INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (1997, 225, 'Q14', 'PERIOD_AGG', 'sql', 'sql', 'SELECT SUM(qty) AS qty FROM scm.sales_daily WHERE sale_date BETWEEN DATE ''2026-09-01'' AND DATE ''2026-09-30'' GROUP BY location_id', true, NULL, 'OK', 1, 0, 0, 2, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (1998, 225, 'Q15', 'METRIC', 'sql', 'sql', 'SELECT i.on_hand::numeric / (SELECT SUM(s.qty)::numeric / 28 FROM scm.sales_daily s WHERE s.sku = ''SKU-026'' AND s.location_id = ''LOC-01'' AND s.sale_date BETWEEN DATE ''2026-10-12'' AND DATE ''2026-11-08'') AS days_of_supply FROM scm.inventory_daily i WHERE i.sku = ''SKU-026'' AND i.location_id = ''LOC-01'' AND i.snap_date = DATE ''2026-11-08''', true, NULL, 'OK', 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (1999, 225, 'Q16', 'METRIC', 'sql', 'sql', 'SELECT AVG(CASE WHEN on_hand = 0 THEN 1.0 ELSE 0.0 END) AS stockout_rate FROM scm.inventory_daily WHERE sku = ''SKU-036'' AND location_id = ''LOC-01''', true, NULL, 'OK', 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2000, 225, 'Q17', 'METRIC', 'sql', 'sql', 'SELECT COUNT(*) AS cnt FROM scm.inventory_daily i JOIN scm.supply_policy p ON p.sku = i.sku AND p.location_id = i.location_id WHERE i.snap_date = DATE ''2026-11-08'' AND i.on_hand < p.safety_stock', true, NULL, 'OK', 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2001, 225, 'Q18', 'METRIC', 'sql', 'sql', 'SELECT COUNT(*) AS cnt FROM scm.inventory_daily i JOIN scm.supply_policy p ON p.sku = i.sku AND p.location_id = i.location_id WHERE i.snap_date = DATE ''2026-11-08'' AND i.on_hand + i.in_transit <= p.reorder_point', true, NULL, 'OK', 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2002, 225, 'Q19', 'METRIC', 'sql', 'sql', 'WITH w AS (SELECT f.week_start, f.location_id, f.forecast_qty, COALESCE(SUM(s.qty), 0) AS actual FROM scm.forecast_weekly f LEFT JOIN scm.sales_daily s ON s.sku = f.sku AND s.location_id = f.location_id AND s.sale_date BETWEEN f.week_start AND f.week_start + 6 WHERE f.sku = ''SKU-008'' GROUP BY f.week_start, f.location_id, f.forecast_qty) SELECT 1 - SUM(ABS(actual - forecast_qty))::numeric / SUM(actual) AS accuracy FROM w', true, NULL, 'OK', 1, 0, 0, 2, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2003, 225, 'Q20', 'METRIC', 'sql', 'sql', 'SELECT SUM(qty)::numeric / 28 AS avg_daily_qty FROM scm.sales_daily WHERE sku = ''SKU-029'' AND sale_date BETWEEN DATE ''2026-10-12'' AND DATE ''2026-11-08''', true, NULL, 'OK', 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2004, 225, 'Q21', 'RANKING', 'sql', 'sql', 'WITH w AS (SELECT f.sku, f.week_start, f.location_id, f.forecast_qty, COALESCE(SUM(s.qty), 0) AS actual FROM scm.forecast_weekly f LEFT JOIN scm.sales_daily s ON s.sku = f.sku AND s.location_id = f.location_id AND s.sale_date BETWEEN f.week_start AND f.week_start + 6 GROUP BY f.sku, f.week_start, f.location_id, f.forecast_qty), a AS (SELECT sku, 1 - SUM(ABS(actual - forecast_qty))::numeric / SUM(actual) AS accuracy FROM w GROUP BY sku) SELECT sku FROM a ORDER BY accuracy ASC, sku LIMIT 4', true, NULL, 'OK', 1, 0, 0, 28, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2005, 225, 'Q22', 'RANKING', 'sql', 'sql', 'SELECT sku FROM scm.sales_daily WHERE sale_date BETWEEN DATE ''2026-11-02'' AND DATE ''2026-11-08'' GROUP BY sku ORDER BY SUM(qty) DESC, sku LIMIT 3', true, NULL, 'OK', 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2006, 225, 'Q23', 'RANKING', 'sql', 'sql', 'SELECT SUM(qty) AS qty FROM scm.sales_daily WHERE sale_date BETWEEN DATE ''2026-10-01'' AND DATE ''2026-10-31'' GROUP BY location_id ORDER BY qty DESC, location_id', true, NULL, 'OK', 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2007, 225, 'Q24', 'RANKING', 'sql', 'sql', 'WITH oh AS (SELECT sku, SUM(on_hand)::numeric AS on_hand FROM scm.inventory_daily WHERE snap_date = DATE ''2026-11-08'' GROUP BY sku), d AS (SELECT sku, SUM(qty)::numeric / 28 AS daily FROM scm.sales_daily WHERE sale_date BETWEEN DATE ''2026-10-12'' AND DATE ''2026-11-08'' GROUP BY sku) SELECT oh.sku FROM oh JOIN d ON d.sku = oh.sku WHERE d.daily > 0 ORDER BY oh.on_hand / d.daily ASC, oh.sku LIMIT 5', true, NULL, 'OK', 1, 0, 0, 2, NULL, NULL, NULL, NULL, NULL, NULL);
