INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2708, 278, 'Q19', 'METRIC', 'sql', 'sql', 'WITH w AS (SELECT f.week_start, f.location_id, f.forecast_qty, COALESCE(SUM(s.qty), 0) AS actual FROM scm.forecast_weekly f LEFT JOIN scm.sales_daily s ON s.sku = f.sku AND s.location_id = f.location_id AND s.sale_date BETWEEN f.week_start AND f.week_start + 6 WHERE f.sku = ''SKU-008'' GROUP BY f.week_start, f.location_id, f.forecast_qty) SELECT 1 - SUM(ABS(actual - forecast_qty))::numeric / SUM(actual) AS accuracy FROM w', true, NULL, 'OK', 1, 0, 0, 5, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2709, 278, 'Q20', 'METRIC', 'sql', 'sql', 'SELECT SUM(qty)::numeric / 28 AS avg_daily_qty FROM scm.sales_daily WHERE sku = ''SKU-029'' AND sale_date BETWEEN DATE ''2026-10-12'' AND DATE ''2026-11-08''', true, NULL, 'OK', 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2710, 278, 'Q21', 'RANKING', 'sql', 'sql', 'WITH w AS (SELECT f.sku, f.week_start, f.location_id, f.forecast_qty, COALESCE(SUM(s.qty), 0) AS actual FROM scm.forecast_weekly f LEFT JOIN scm.sales_daily s ON s.sku = f.sku AND s.location_id = f.location_id AND s.sale_date BETWEEN f.week_start AND f.week_start + 6 GROUP BY f.sku, f.week_start, f.location_id, f.forecast_qty), a AS (SELECT sku, 1 - SUM(ABS(actual - forecast_qty))::numeric / SUM(actual) AS accuracy FROM w GROUP BY sku) SELECT sku FROM a ORDER BY accuracy ASC, sku LIMIT 4', true, NULL, 'OK', 1, 0, 0, 46, NULL, NULL, NULL, NULL, NULL, NULL);
