INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3187, 295, 'Q68', 'AMBIGUOUS', 'clarify', 'clarify', NULL, true, NULL, 'OK', 1, 4581, 64, 4990, NULL, 'clarify', NULL, NULL, NULL, NULL);
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2798, 281, 'Q19', 'METRIC', 'sql', 'sql', 'WITH w AS (SELECT f.week_start, f.location_id, f.forecast_qty, COALESCE(SUM(s.qty), 0) AS actual FROM scm.forecast_weekly f LEFT JOIN scm.sales_daily s ON s.sku = f.sku AND s.location_id = f.location_id AND s.sale_date BETWEEN f.week_start AND f.week_start + 6 WHERE f.sku = ''SKU-008'' GROUP BY f.week_start, f.location_id, f.forecast_qty) SELECT 1 - SUM(ABS(actual - forecast_qty))::numeric / SUM(actual) AS accuracy FROM w LIMIT 200', true, NULL, 'OK', 3, 0, 0, 7, NULL, 'sql', NULL, NULL, NULL, 'SKIPPED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2799, 281, 'Q20', 'METRIC', 'sql', 'sql', 'SELECT SUM(qty)::numeric / 28 AS avg_daily_qty FROM scm.sales_daily WHERE sku = ''SKU-029'' AND sale_date BETWEEN DATE ''2026-10-12'' AND DATE ''2026-11-08'' LIMIT 200', true, NULL, 'OK', 3, 0, 0, 4, NULL, 'sql', NULL, NULL, NULL, 'SKIPPED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2800, 281, 'Q21', 'RANKING', 'sql', 'sql', 'WITH w AS (SELECT f.sku, f.week_start, f.location_id, f.forecast_qty, COALESCE(SUM(s.qty), 0) AS actual FROM scm.forecast_weekly f LEFT JOIN scm.sales_daily s ON s.sku = f.sku AND s.location_id = f.location_id AND s.sale_date BETWEEN f.week_start AND f.week_start + 6 GROUP BY f.sku, f.week_start, f.location_id, f.forecast_qty), a AS (SELECT sku, 1 - SUM(ABS(actual - forecast_qty))::numeric / SUM(actual) AS accuracy FROM w GROUP BY sku) SELECT sku FROM a ORDER BY accuracy ASC, sku LIMIT 4', true, NULL, 'OK', 3, 0, 0, 38, NULL, 'sql', NULL, NULL, NULL, 'SKIPPED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (2801, 281, 'Q22', 'RANKING', 'sql', 'sql', 'SELECT sku FROM scm.sales_daily WHERE sale_date BETWEEN DATE ''2026-11-02'' AND DATE ''2026-11-08'' GROUP BY sku ORDER BY SUM(qty) DESC, sku LIMIT 3', true, NULL, 'OK', 3, 0, 0, 6, NULL, 'sql', NULL, NULL, NULL, 'SKIPPED');
