INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3207, 296, 'Q88', 'RANKING', 'sql', 'sql', 'SELECT l.name AS location_name, 1 - (SELECT SUM(ABS(s.qty - f.forecast_qty))::numeric / SUM(s.qty) FROM sales_daily s JOIN forecast_weekly f ON f.sku = s.sku AND f.location_id = s.location_id WHERE f.week_start BETWEEN DATE ''2026-08-10'' AND DATE ''2026-11-02'' AND s.sale_date BETWEEN f.week_start AND f.week_start + 6) AS accuracy FROM location l JOIN inventory_daily i ON i.location_id = l.location_id WHERE i.snap_date = DATE ''2026-11-08'' ORDER BY accuracy DESC LIMIT 1', false, 'METRIC_DEFINITION', 'OK', 3, 6972, 228, 17610, 'no column matches expected column name', 'sql', 'forecast_accuracy', '{"output":"ranking","top_n":1,"order":"desc","guard":"question ranks locations, regions or categories, not items"}', '예측 정확도가 가장 높은 거점은 서울센터입니다.', 'VERIFIED');
