INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3303, 314, 'Q36', 'METRIC', 'sql', 'sql', 'SELECT p.category, AVG(s.qty) AS avg_sales FROM sales_daily s JOIN product p ON p.sku = s.sku WHERE s.sale_date BETWEEN DATE ''2026-10-12'' AND DATE ''2026-11-08'' GROUP BY p.category LIMIT 200', false, 'METRIC_DEFINITION', 'OK', 3, 7077, 204, 15527, 'no column matches expected column avg_daily_qty', 'sql', 'avg_daily_sales', '{"days":28,"output":"ranking","order":"desc","guard":"rejected: top_n must be 1..50 for ranking: 0"}', '카테고리별 최근 28일 일평균 판매량은 다음과 같습니다:
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3306, 314, 'Q39', 'RANKING', 'sql', 'sql', 'SELECT l.name AS location_name, COUNT(*) AS zero_stock_count FROM inventory_daily i JOIN location l ON l.location_id = i.location_id WHERE i.snap_date = DATE ''2026-11-08'' AND i.on_hand = 0 GROUP BY l.name ORDER BY zero_stock_count DESC LIMIT 1', false, 'METRIC_DEFINITION', 'OK', 3, 6951, 149, 11363, 'no column matches expected column name', 'sql', 'stockout_rate', '{"output":"ranking","top_n":1,"order":"desc","guard":"question picks a location, region or category, not an item"}', '결품률이 가장 높은 거점은 대구센터입니다.', 'VERIFIED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3311, 314, 'Q44', 'RANKING', 'sql', 'sql', 'SELECT fw.week_start, ABS(SUM(sd.qty) - SUM(fw.forecast_qty)) AS diff FROM sales_daily sd JOIN forecast_weekly fw ON sd.sku = fw.sku AND sd.location_id = fw.location_id AND sd.sale_date BETWEEN DATE ''2026-08-10'' AND DATE ''2026-11-02'' AND fw.week_start BETWEEN DATE ''2026-08-10'' AND DATE ''2026-11-02'' WHERE sd.sku = ''SKU-021'' GROUP BY fw.week_start ORDER BY diff DESC LIMIT 1', false, 'JOIN_AGGREGATION', 'OK', 4, 9243, 381, 28773, 'no column matches expected column week_start', 'sql', NULL, NULL, 'SKU-021의 최근 13주 중 예측과 실적 차이가 가장 컸던 주는 2026-08-10입니다.', 'VERIFIED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3312, 314, 'Q45', 'PERIOD_AGG', 'sql', 'sql', 'SELECT p.sku, l.name FROM product p JOIN sales_daily s ON s.sku = p.sku JOIN location l ON l.location_id = s.location_id WHERE s.sale_date BETWEEN DATE ''2026-11-02'' AND DATE ''2026-11-08'' AND s.qty = 0 GROUP BY p.sku, l.name LIMIT 200', false, 'JOIN_AGGREGATION', 'OK', 3, 6998, 173, 13127, 'row count differs: expected 2 but was 4', 'sql', NULL, NULL, '최근 7일 동안 판매가 한 건도 없었던 SKU-거점은 대구센터, 서울센터, 부산센터, 대전센터입니다.', 'VERIFIED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3348, 316, 'Q81', 'METRIC', 'sql', 'sql', 'SELECT COUNT(*) FROM inventory_daily i JOIN supply_policy p ON p.sku = i.sku AND p.location_id = i.location_id WHERE i.snap_date = DATE ''2026-11-08'' AND i.on_hand / NULLIF((SELECT SUM(qty) FROM sales_daily WHERE sku = i.sku AND sale_date BETWEEN DATE ''2026-10-12'' AND DATE ''2026-11-08'')::numeric / 28, 0) < 3 LIMIT 200', false, 'JOIN_AGGREGATION', 'OK', 3, 6964, 235, 18095, 'no column matches expected column cnt', 'sql', NULL, NULL, '재고보유일수가 3일 미만인 SKU-거점은 227개입니다.', 'VERIFIED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3349, 316, 'Q82', 'METRIC', 'sql', 'sql', 'SELECT COUNT(DISTINCT sku) FROM sales_daily WHERE sale_date BETWEEN DATE ''2026-11-02'' AND DATE ''2026-11-08'' AND qty < (SELECT SUM(qty) FROM sales_daily WHERE sale_date BETWEEN DATE ''2026-10-26'' AND DATE ''2026-11-01'' AND sku = sales_daily.sku) LIMIT 200', false, 'JOIN_AGGREGATION', 'OK', 3, 6986, 180, 14143, 'no column matches expected column cnt', 'sql', NULL, NULL, '최근 7일 판매량이 그 직전 7일보다 줄어든 품목은 50개입니다.', 'VERIFIED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3355, 316, 'Q88', 'RANKING', 'sql', 'sql', 'SELECT l.name AS location_name, 1 - (SELECT SUM(ABS(s.qty - f.forecast_qty))::numeric / SUM(s.qty) FROM sales_daily s JOIN forecast_weekly f ON f.sku = s.sku AND f.location_id = s.location_id WHERE f.week_start BETWEEN DATE ''2026-08-10'' AND DATE ''2026-11-02'' AND s.sale_date BETWEEN f.week_start AND f.week_start + 6) AS accuracy FROM location l JOIN inventory_daily i ON i.location_id = l.location_id WHERE i.snap_date = DATE ''2026-11-08'' ORDER BY accuracy DESC LIMIT 1', false, 'METRIC_DEFINITION', 'OK', 3, 6972, 228, 17439, 'no column matches expected column name', 'sql', 'forecast_accuracy', '{"output":"ranking","top_n":1,"order":"desc","guard":"question picks a location, region or category, not an item"}', '예측 정확도가 가장 높은 거점은 서울센터입니다.', 'VERIFIED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3360, 316, 'Q93', 'PERIOD_AGG', 'sql', 'sql', 'SELECT SUM(qty) AS total_sales FROM sales_daily WHERE location_id = (SELECT location_id FROM location WHERE name = ''부산센터'') AND sale_date BETWEEN DATE ''2023-09-14'' AND DATE ''2023-09-20'' LIMIT 200', false, 'DATE_RANGE', 'OK', 3, 6949, 158, 12086, 'no column matches expected column qty', 'sql', NULL, NULL, '9/14~9/20 부산센터 판매량은 없습니다.', 'VERIFIED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3362, 316, 'Q95', 'PERIOD_AGG', 'sql', 'sql', 'SELECT SUM(qty) AS total_qty FROM sales_daily WHERE sale_date = DATE ''2026-11-07'' ORDER BY total_qty DESC LIMIT 1', false, 'JOIN_AGGREGATION', 'OK', 3, 6960, 117, 9204, 'no column matches expected column qty', 'sql', NULL, NULL, '어제 가장 많이 팔린 품목은 6373개 팔렸습니다.', 'VERIFIED');
INSERT INTO app.eval_result (id, run_id, question_id, qtype, expected_action, actual_action, generated_sql, correct, error_type, status, attempts, prompt_tokens, completion_tokens, elapsed_ms, detail, route, tool_name, tool_args, answer_text, answer_status) VALUES (3366, 316, 'Q99', 'SIMPLE_LOOKUP', 'sql', 'sql', 'SELECT forecast_qty FROM forecast_weekly WHERE sku = ''SKU-046'' AND week_start = DATE ''2026-11-02'' LIMIT 200', false, 'JOIN_AGGREGATION', 'OK', 3, 6947, 163, 12709, 'row count differs: expected 1 but was 5', 'sql', 'forecast_accuracy', '{"sku":"SKU-046","output":"value","guard":"question does not name the metric of the tool"}', 'SKU-046의 이번 주 예측 수량은 5개입니다.', 'VERIFIED');
